#include <linux/fs.h>

void init_inode_owner(struct inode *inode, const struct inode *dir, umode_t mode) {
    inode->i_uid = current_fsuid();

    if (dir && (dir->i_mode & S_ISGID)) {
        inode->i_gid = dir->i_gid;
        if (S_ISDIR(mode)) {
            mode |= S_ISGID;
        }
    } else {
        inode->i_gid = current_fsgid().val;
    }

    inode->i_mode = mode;
}
